// @vitest-environment jsdom
// Golden exports of the seeded Chinese learner (fixtures/learner.ts): the app's own code writes the JSON backup, the profile
// YAML and the cloud-backup files (settings.yaml, manifest, state, journal segment, ...), and each must equal the committed
// file in fixtures/golden/ byte for byte. These are the "Chinese is unchanged" checks of the language-pack work.
//
// A failure prints the changed lines (a line-by-line diff), not a hash. Nothing is ever regenerated by itself. To accept a
// deliberate change, regenerate and review the diff in git:
//
//   LINGUAWEAVE_UPDATE_GOLDEN=1 npx vitest run src/core/profiles/golden-exports.test.ts
//
// Goldens are LF text compared as bytes, read and written without any newline conversion, so Windows and Linux agree.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse } from 'yaml'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { db, initializeWorkspace } from '../database'
import { exportWorkspaceBackup, restoreBackup } from '../backup'
import { exportBackup, readBackup } from '../backup-codec'
import type { BackupBackend, DeltaResult, PublishResult, RemoteState } from '../backup/backend'
import { dump, buildFilesV2, loadBackupV2, type SequencedEvent } from '../backup/layout'
import { parseJournal } from '../backup/journal'
import { applyBackup, loadBackupVersion, runBackup, saveBackupConfig, setBackendFactoryForTests, type BackupConfig } from '../backup/service'
import { resetBackupStateForTests } from '../backup/state'
import { getActiveProfile, initializeProfiles, readSnapshot, restoreActiveProfile } from './store'
import { parseProfileYaml, serializeProfileYaml } from './codec'
import { learnerFixture, T0, type LearnerFixture } from './fixtures/learner'

const here = dirname(fileURLToPath(import.meta.url))
const GOLDEN = join(here, 'fixtures', 'golden')
const UPDATE = process.env.LINGUAWEAVE_UPDATE_GOLDEN === '1'
const config: BackupConfig = { owner: 'me', repo: 'backups', token: 'synthetic-token', branch: 'main' }
const FIXED_REVISION = '00000000-0000-4000-8000-000000000102'

function memoryBackend() {
  const versions: { id: string; files: Map<string, string> }[] = []
  const remoteOf = (map: Map<string, string>, head: string): RemoteState => ({ head, tree: 't', files: Object.fromEntries([...map].map(([path, text]) => [path, String(text.length)])) })
  const backend: BackupBackend = {
    listProfiles: async () => versions.length ? [{ id: 'default', name: 'default' }] : [],
    listVersions: async () => [...versions].reverse().map(({ id }) => ({ id, date: new Date(T0).toISOString(), message: 'backup' })),
    readFiles: async (_profile, version) => new Map((version ? versions.find(item => item.id === version)! : versions.at(-1)!).files),
    publish: async (_profile, files): Promise<PublishResult> => { versions.push({ id: 'v' + (versions.length + 1), files: new Map(files) }); return { version: 'v' + versions.length, changed: files.size, removed: 0 } },
    publishDelta: async (_profile, files, keep): Promise<DeltaResult> => {
      const next = new Map(files)
      for (const path of keep) next.set(path, versions.at(-1)!.files.get(path)!)
      const id = 'v' + (versions.length + 1)
      versions.push({ id, files: next })
      return { version: id, changed: next.size, removed: 0, remote: remoteOf(next, id), calls: [] }
    },
  }
  return { backend, versions }
}

async function reset() {
  await resetBackupStateForTests()
  localStorage.clear()
  await initializeProfiles()
  await db.delete()
  await db.open()
  await initializeWorkspace()
}

async function seed(fixture: LearnerFixture) {
  const { restoreActiveSnapshot } = await import('./store')
  await restoreActiveSnapshot(fixture.snapshot, fixture.journal)
  const { drillSets, sudokuBoards, skillPractice, phraseHeard, userPhrases } = fixture.extras
  await db.drillSets.bulkAdd(drillSets)
  await db.table('sudokuGames').bulkAdd(sudokuBoards)
  await db.skillPractice.bulkAdd(skillPractice)
  await db.phraseHeard.bulkAdd(phraseHeard)
  await db.userPhrases.bulkAdd(userPhrases)
}

/** What the app writes today for the seeded profile, in every stored form. */
async function exportAll(fixture: LearnerFixture) {
  await seed(fixture)
  const memory = memoryBackend()
  setBackendFactoryForTests(() => memory.backend)
  await saveBackupConfig(config)
  await runBackup('manual')
  return {
    json: await exportWorkspaceBackup(),
    yaml: serializeProfileYaml(await readSnapshot(db, getActiveProfile())),
    cloud: new Map([...memory.versions.at(-1)!.files].sort(([a], [b]) => a.localeCompare(b))),
  }
}

/** The counts the fixture promises, from the app's readers over the database. */
async function dbCounts() {
  return {
    knowledge: await db.knowledge.count(), cards: await db.studyCards.count(), exerciseSessions: await db.exerciseSessions.count(), exerciseAttempts: await db.exerciseAttempts.count(),
    characterStates: await db.characterStates.count(), words: await db.words.count(), readings: await db.readings.count(), lessons: await db.lessons.count(),
    sessions: await db.sessions.count(), attempts: await db.attempts.count(), threads: await db.assistantThreads.count(), messages: await db.assistantMessages.count(),
    runs: await db.assistantRuns.count(), library: await db.libraryBooks.count(), collections: await db.collections.count(), collectionItems: await db.collectionItems.count(),
    drillSets: await db.drillSets.count(), sudokuBoards: await db.table('sudokuGames').count(), skillPractice: await db.skillPractice.count(),
    phraseHeard: await db.phraseHeard.count(), userPhrases: await db.userPhrases.count(),
  }
}
const profileOnly = ['media', 'sourceEntries'] as const

export function fixtureCounts(fixture: LearnerFixture) {
  const { snapshot: s, extras: e } = fixture
  return {
    knowledge: s.knowledge.study.knowledge.length, cards: s.knowledge.study.cards.length + s.collections.cards.length, exerciseSessions: s.knowledge.study.sessions.length, exerciseAttempts: s.knowledge.study.attempts.length,
    characterStates: s.knowledge.characterStates.length, words: s.knowledge.words.length, readings: s.knowledge.readings.length, lessons: s.knowledge.lessons.length,
    sessions: s.knowledge.sessions.length, attempts: s.knowledge.attempts.length, threads: s.conversations.threads.length, messages: s.conversations.messages.length,
    runs: s.conversations.runs.length, library: s.library.length, collections: s.collections.collections.length, collectionItems: s.collections.items.length,
    drillSets: e.drillSets.length, sudokuBoards: e.sudokuBoards.length, skillPractice: e.skillPractice.length, phraseHeard: e.phraseHeard.length, userPhrases: e.userPhrases.length,
  }
}

// ---- golden files ----
const goldenPath = (name: string) => join(GOLDEN, ...name.split('/'))
function listGolden(dir = GOLDEN): string[] {
  if (!existsSync(dir)) return []
  return readdirSync(dir).flatMap(entry => {
    const path = join(dir, entry)
    return statSync(path).isDirectory() ? listGolden(path) : [relative(GOLDEN, path).split(sep).join('/')]
  }).sort()
}

/** Compares as bytes; on a difference fails with the changed lines. Only the export test (writable) may regenerate a file: round-trip tests never do. */
function expectGolden(name: string, actual: string, writable = false) {
  const path = goldenPath(name)
  if (UPDATE && writable) { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, actual) }
  expect(existsSync(path), name + ' is missing; regenerate with LINGUAWEAVE_UPDATE_GOLDEN=1').toBe(true)
  const golden = readFileSync(path)
  expect(golden.includes(13), name + ' must be LF only').toBe(false)
  if (!golden.equals(Buffer.from(actual, 'utf8'))) {
    expect(actual.split('\n'), name + ' differs from its golden file').toEqual(golden.toString('utf8').split('\n'))
    throw new Error(name + ' differs from its golden file in bytes only (BOM or encoding)')
  }
}

let fixture: LearnerFixture
beforeEach(async () => {
  vi.useFakeTimers({ toFake: ['Date'] })
  vi.setSystemTime(T0)
  vi.spyOn(crypto, 'randomUUID').mockReturnValue(FIXED_REVISION as ReturnType<typeof crypto.randomUUID>)
  fixture = learnerFixture()
  await reset()
})
afterEach(() => { setBackendFactoryForTests(undefined); vi.useRealTimers(); vi.restoreAllMocks() })

describe('the seeded Chinese learner', () => {
  it('is deterministic and Chinese only', () => {
    expect(learnerFixture()).toEqual(learnerFixture())
    const refs = JSON.stringify(fixture.snapshot)
    expect(refs).not.toMatch(/"(?:ja|ko):|startedTracks|currentLanguage/)
    const counts = fixtureCounts(fixture)
    expect(counts.knowledge).toBeGreaterThanOrEqual(150) // the 400 KB budget for all goldens is what limits this
    const kinds = new Set(fixture.snapshot.knowledge.study.knowledge.map(entry => entry.kind))
    expect([...kinds].sort()).toEqual(['grammar', 'source', 'vocabulary'])
    const states = new Set(fixture.snapshot.knowledge.study.cards.map(card => card.state))
    expect([...states].sort()).toEqual(['learning', 'new', 'relearning', 'review'])
  })
})

describe('golden exports', () => {
  it('writes every stored form exactly as the golden files hold it', async () => {
    const out = await exportAll(fixture)
    expectGolden('backup.json', out.json, true)
    expectGolden('profile.yaml', out.yaml, true)
    for (const [path, text] of out.cloud) expectGolden('cloud/' + path, text, true)
    // no file may be missing from the repository's set, nor an old one left behind
    const expected = ['backup.json', 'profile.yaml', ...[...out.cloud.keys()].map(path => 'cloud/' + path)].sort()
    if (UPDATE) for (const stale of listGolden().filter(name => !expected.includes(name))) rmSync(goldenPath(stale))
    expect(listGolden()).toEqual(expected)
    expect(out.cloud.has('settings.yaml') && out.cloud.has('manifest.yaml') && out.cloud.has('state/snapshot.yaml') && [...out.cloud.keys()].some(path => path.startsWith('journal/'))).toBe(true)
  })

  it('keeps the golden set small', () => {
    const total = listGolden().reduce((sum, name) => sum + statSync(goldenPath(name)).size, 0)
    expect(total).toBeLessThan(400 * 1024)
  })
})

describe('golden round trips', () => {
  const read = (name: string) => readFileSync(goldenPath(name), 'utf8')

  it('JSON backup: read then export again gives the same bytes', () => {
    expectGolden('backup.json', exportBackup(readBackup(read('backup.json'))))
  })

  it('profile YAML: parse then serialize again gives the same bytes', () => {
    expectGolden('profile.yaml', serializeProfileYaml(parseProfileYaml(read('profile.yaml'))))
  })

  it('settings.yaml: parse then dump again gives the same bytes', () => {
    expectGolden('cloud/settings.yaml', dump(parse(read('cloud/settings.yaml'))))
  })

  it('cloud files: loading the golden set and building it again gives the same files', () => {
    const files = new Map(listGolden().filter(name => name.startsWith('cloud/')).map(name => [name.slice('cloud/'.length), read(name)] as const))
    const loaded = loadBackupV2(files, { id: 'default', name: 'default' })
    const manifest = parse(files.get('manifest.yaml')!) as { cursor: number; segments: { path: string; from: number; to: number; events: number }[] }
    const fresh = manifest.segments.flatMap(segment => parseJournal(files.get(segment.path)!).map((event, n) => ({ ...event, seq: segment.from + n }) as SequencedEvent))
    const s = loaded.snapshot
    const rebuilt = buildFilesV2({
      profile: loaded.profile as { id: string; name: string }, settings: s.settings, cursor: manifest.cursor, fresh, existing: [], snapshotDue: true, first: true, snapshotCursor: 0, connection: loaded.backup,
      state: { knowledge: s.knowledge.study.knowledge, cards: s.knowledge.study.cards, attempts: s.knowledge.study.attempts, characters: s.knowledge.characterStates },
      unjournaled: {
        words: s.knowledge.words, readings: s.knowledge.readings, lessons: s.knowledge.lessons, sessions: s.knowledge.sessions, attempts: s.knowledge.attempts,
        exerciseSessions: s.knowledge.study.sessions, practiceHistory: s.conversations.practiceHistory ?? [], threads: s.conversations.threads, messages: s.conversations.messages,
        runs: s.conversations.runs, library: s.library, media: s.media, sourceEntries: s.sourceEntries, collections: s.collections,
      },
    })
    expect([...rebuilt.files.keys()].sort()).toEqual([...files.keys()].sort())
    for (const [path, text] of rebuilt.files) expectGolden('cloud/' + path, text)
  })

  it('profile YAML: restore into an empty profile, read it back, same bytes and the fixture counts', async () => {
    await restoreActiveProfile(read('profile.yaml'))
    expect(await dbCounts()).toEqual({ ...fixtureCounts(fixture), drillSets: 0, sudokuBoards: 0, skillPractice: 0, phraseHeard: 0, userPhrases: 0 })
    expect(await db.mediaItems.count()).toBe(fixture.snapshot.media.length)
    expect(await db.sourceEntries.count()).toBe(fixture.snapshot.sourceEntries.length)
    expectGolden('profile.yaml', serializeProfileYaml(await readSnapshot(db, getActiveProfile())))
  })

  it('JSON backup: restore into an empty database, read it back, same bytes and the fixture counts', async () => {
    expect(await db.knowledge.count()).toBe(0)
    await restoreBackup(read('backup.json'))
    expect(await dbCounts()).toEqual(fixtureCounts(fixture))
    for (const table of profileOnly) expect(await db.table(table === 'media' ? 'mediaItems' : table).count()).toBe(0) // the JSON backup never carried these
    expectGolden('backup.json', await exportWorkspaceBackup())
  })

  it('cloud backup: restore the golden set into an empty profile, same counts, and a new backup writes the same files', async () => {
    const files = new Map(listGolden().filter(name => name.startsWith('cloud/')).map(name => [name.slice('cloud/'.length), read(name)] as const))
    const memory = memoryBackend()
    memory.versions.push({ id: 'v1', files })
    setBackendFactoryForTests(() => memory.backend)
    await saveBackupConfig(config)
    await applyBackup(await loadBackupVersion(config, 'default'), config)
    const counts = await dbCounts()
    expect({ ...counts, drillSets: 0, sudokuBoards: 0, skillPractice: 0, phraseHeard: 0, userPhrases: 0 }).toEqual({ ...fixtureCounts(fixture), drillSets: 0, sudokuBoards: 0, skillPractice: 0, phraseHeard: 0, userPhrases: 0 })
    expect(await db.mediaItems.count()).toBe(fixture.snapshot.media.length)
    expect(await db.sourceEntries.count()).toBe(fixture.snapshot.sourceEntries.length)
    expectGolden('profile.yaml', serializeProfileYaml(await readSnapshot(db, getActiveProfile())))
  })
})
